_DESCRIPTIONS={
"plants":{"es":"Observación de naturaleza y conocimiento botánico general. No hace falta tocar, cortar ni ingerir la planta.","en":"Nature observation and general botanical knowledge. There is no need to touch, cut or eat the plant."},
"movement":{"es":"Movimiento cotidiano suave y adaptable. Haz solo lo que resulte cómodo y seguro; detente si aparece dolor o mareo.","en":"Gentle, adaptable everyday movement. Do only what feels comfortable and safe; stop if pain or dizziness occurs."},
"calm":{"es":"Pausa general de atención al presente. Respira con naturalidad; no es un tratamiento médico.","en":"A general present-moment pause. Breathe naturally; this is not medical treatment."},
"coach":{"es":"Actividad sencilla para organizar prioridades y elegir un siguiente paso práctico.","en":"A simple activity to organize priorities and choose a practical next step."}}

def _make_catalog():
    out=[]
    for section in ("movement","calm","coach"):
        for i,(es,en) in enumerate(_TITLES[section]):
            out.append({"id":f"{section}_{i+1:02d}","section":section,"title":{"es":es,"en":en},"description":_DESCRIPTIONS[section],"steps":_STEP_PAIRS[section],"plant_id":None,"index":i})
    for i,p in enumerate(PLANTS.values()):
        out.append({"id":f"plant_{p['id']}","section":"plants","title":p["activity"],"description":_DESCRIPTIONS["plants"],"steps":_STEP_PAIRS["plants"],"plant_id":p["id"],"index":i})
    return out

_CATALOG=_make_catalog()
_BY_ID={x["id"]:x for x in _CATALOG}
for _i,_p in enumerate(PLANTS.values(),1):
    _p["legacy_id"]=f"p{_i:02d}"

def _plant_key(plant_id):
    pid=str(plant_id or "").strip().lower()
    if pid in PLANTS:return pid
    for key,p in PLANTS.items():
        if pid==p["legacy_id"].lower() or pid==p["name"]["es"].lower() or pid==p["name"]["en"].lower():
            return key
    return None

def _local_steps(item,lang):
    steps=item.get("steps",[])
    if item["section"]=="plants" and item.get("plant_id") in PLANTS:
        p=PLANTS[item["plant_id"]]
        custom=[(p["observation"]["es"],p["observation"]["en"]),(p["characteristics"]["es"],p["characteristics"]["en"]),(p["wellness_relation"]["es"],p["wellness_relation"]["en"]),(p["precautions"]["es"],p["precautions"]["en"])]
        steps=list(custom)+list(steps[4:])
    if not steps:return []
    shift=(item.get("index",0)*3)%len(steps)
    steps=steps[shift:]+steps[:shift]
    return [_b(pair[0],pair[1],lang) for pair in steps]

def _plant_public(p,lang):
    return {
        "id":p["id"],
        "legacy_id":p["legacy_id"],
        "name":_b(p["name"]["es"],p["name"]["en"],lang),
        "scientific_name":p["scientific_name"],
        "scientific":p["scientific_name"],
        "group":p["group"],
        "characteristics":_b(p["characteristics"]["es"],p["characteristics"]["en"],lang),
        "description":_b(p["description"]["es"],p["description"]["en"],lang),
        "habitat":_b(p["habitat"]["es"],p["habitat"]["en"],lang),
        "pot_suitability":_b(p["pot_suitability"]["es"],p["pot_suitability"]["en"],lang),
        "care":_b(p["care"]["es"],p["care"]["en"],lang),
        "traditional_use":_b(p["traditional_use"]["es"],p["traditional_use"]["en"],lang),
        "ornamental_use":_b(p["ornamental_use"]["es"],p["ornamental_use"]["en"],lang),
        "did_you_know":_b(p["did_you_know"]["es"],p["did_you_know"]["en"],lang),
        "growing_tip":_b(p["growing_tip"]["es"],p["growing_tip"]["en"],lang),
        "wellness_relation":_b(p["wellness_relation"]["es"],p["wellness_relation"]["en"],lang),
        "observation":_b(p["observation"]["es"],p["observation"]["en"],lang),
        "precautions":_b(p["precautions"]["es"],p["precautions"]["en"],lang),
        "activity":_b(p["activity"]["es"],p["activity"]["en"],lang),
        "curiosity":_b(p["curiosity"]["es"],p["curiosity"]["en"],lang),
        "image_prompt":p["image_prompt"],
        "image_url":p["image_url"],
        "image_license":p["image_license"],
        "photo_source":p["photo_source"],
        "photos":[],
        "photo_search_terms":[p["scientific_name"],_b(p["name"]["es"],p["name"]["en"],lang)],
        "disclaimer":_b(p["disclaimer"]["es"],p["disclaimer"]["en"],lang)
    }

def _public_activity(item,lang="es",minutes=None):
    lang=_valid_lang(lang)
    data={"id":item["id"],"section":item["section"],"title":_b(item["title"]["es"],item["title"]["en"],lang),"description":_b(item["description"]["es"],item["description"]["en"],lang),"steps":_local_steps(item,lang),"plant_id":item.get("plant_id"),"step_count":20}
    if minutes is not None:data["minutes"]=int(minutes)
    pid=item.get("plant_id")
    if pid in PLANTS:
        data["plant"]=_plant_public(PLANTS[pid],lang)
    return data

def get_catalog(lang="es"):
    lang=_valid_lang(lang)
    names={"plants":("Plantas y naturaleza","Plants and nature"),"movement":("Movimiento suave","Gentle movement"),"calm":("Calma y atención","Calm and attention"),"coach":("Coach y planificación","Coaching and planning")}
    return {"app":APP_NAME,"company":COMPANY,"version":VERSION,"language":lang,"sections":[{"id":s,"name":_b(*names[s],lang),"count":sum(1 for x in _CATALOG if x["section"]==s)} for s in SECTIONS],"activities":[_public_activity(x,lang) for x in _CATALOG],"plant_count":len(PLANTS),"durations":list(MINUTES_ALLOWED)}

def get_activities(lang="es",section="all"):
    lang=_valid_lang(lang)
    section=section if section in (*SECTIONS,"all") else "all"
    return [_public_activity(x,lang) for x in _CATALOG if section=="all" or x["section"]==section]

def get_activity(activity_id,lang="es"):
    item=_BY_ID.get(str(activity_id or ""))
    return _public_activity(item,lang) if item else None

def get_plant(plant_id,lang="es"):
    lang=_valid_lang(lang)
    pid=_plant_key(plant_id)
    if not pid:return None
    return _plant_public(PLANTS[pid],lang)

def _section_for_kind(kind):
    kind=str(kind or "pause").lower()
    return {"pause":"calm","energy":"movement","calm":"calm","nature":"plants","plants":"plants","movement":"movement","coach":"coach","program":"all"}.get(kind,"calm")

def _duration(value):
    try:value=int(value)
    except (TypeError,ValueError):value=3
    return value if value in MINUTES_ALLOWED else min(MINUTES_ALLOWED,key=lambda x:abs(x-value))

def _choose_activity(pool,lang,allow_repeat=False,avoid_ids=None):
    if not pool:pool=[x for x in _CATALOG if x["section"]=="calm"]
    if allow_repeat:return _RNG.choice(pool)
    key=f"{_valid_lang(lang)}|{pool[0]['section'] if len({x['section'] for x in pool})==1 else 'all'}"
    with _LOCK:
        seen=_HISTORY.setdefault(key,[])
        fresh=[x for x in pool if x["id"] not in seen and (not avoid_ids or x["id"] not in avoid_ids)]
        if not fresh:
            seen.clear()
            fresh=[x for x in pool if not avoid_ids or x["id"] not in avoid_ids]
        if not fresh:fresh=list(pool)
        item=_RNG.choice(fresh)
        seen.append(item["id"])
        if len(seen)>_MAX_HISTORY:del seen[:-_MAX_HISTORY]
        return item

def get_session(activity_id=None,minutes=3,lang="es",activity=None,kind=None,allow_repeat=False,avoid_ids=None):
    # Compatibilidad con main.py: get_session(lang,kind,minutes).
    if activity_id in LANGUAGES and isinstance(minutes,str):
        old_lang=activity_id
        old_kind=minutes
        try:old_minutes=int(lang)
        except (TypeError,ValueError):old_minutes=3
        lang=old_lang
        kind=old_kind
        minutes=old_minutes
        activity_id=None
    lang=_valid_lang(lang)
    minutes=_duration(minutes)
    if isinstance(activity,dict):activity_id=activity.get("id",activity_id)
    item=_BY_ID.get(str(activity_id or ""))
    if item is None:
        section=_section_for_kind(kind or activity_id)
        pool=[x for x in _CATALOG if section=="all" or x["section"]==section]
        item=_choose_activity(pool,lang,allow_repeat,avoid_ids)
    elif not allow_repeat:
        with _LOCK:
            key=f"{lang}|{item['section']}"
            seen=_HISTORY.setdefault(key,[])
            if item["id"] not in seen:seen.append(item["id"])
    result=_public_activity(item,lang,minutes)
    result.update({"app":APP_NAME,"version":VERSION,"language":lang,"duration_seconds":minutes*60,"prompt_interval_seconds":PROMPT_INTERVAL_SECONDS,"session_id":create_session_id(item["id"],minutes),"instructions":result["steps"],"total_steps":len(result["steps"]),"allow_repeat":bool(allow_repeat),"can_clear":True})
    return result

def get_program_day(lang="es",day=1):
    lang=_valid_lang(lang)
    try:day=int(day)
    except (TypeError,ValueError):day=1
    day=max(1,min(7,day))
    sequence=("calm","plants","movement","coach","calm","plants","coach")
    section=sequence[day-1]
    pool=[x for x in _CATALOG if x["section"]==section]
    item=pool[(day*7-7)%len(pool)]
    es=["Comenzar con calma","Observar la naturaleza","Moverse suavemente","Organizar un paso","Volver al presente","Descubrir detalles verdes","Elegir el siguiente paso"]
    en=["Begin calmly","Observe nature","Move gently","Organize one step","Return to the present","Discover green details","Choose the next step"]
    desc_es=["Una pausa sencilla para empezar.","Observa detalles naturales con curiosidad.","Prueba movimientos suaves y cómodos.","Elige una prioridad pequeña y realista.","Dedica unos minutos a notar tu entorno.","Observa una planta sin prisa.","Termina la semana con una acción concreta."]
    desc_en=["A simple pause to begin.","Notice natural details with curiosity.","Try gentle, comfortable movements.","Choose one small, realistic priority.","Spend a few minutes noticing your surroundings.","Observe a plant without rushing.","Finish the week with one concrete action."]
    mins=(3,5,3,5,10,5,10)[day-1]
    return {"day":day,"title":_b(es[day-1],en[day-1],lang),"description":_b(desc_es[day-1],desc_en[day-1],lang),"minutes":mins,"activity":_public_activity(item,lang,mins),"section":section,"prompt_interval_seconds":PROMPT_INTERVAL_SECONDS}

def get_health():
    return {"status":"ok","app":APP_NAME,"version":VERSION,"activities":len(_CATALOG),"plants":len(PLANTS),"durations":list(MINUTES_ALLOWED),"languages":list(LANGUAGES)}

def get_config():
    return {"name":APP_NAME,"company":COMPANY,"version":VERSION,"languages":list(LANGUAGES),"durations":list(MINUTES_ALLOWED),"sections":list(SECTIONS),"activity_count":len(_CATALOG),"plant_count":len(PLANTS),"program_days":7,"prompt_interval_seconds":PROMPT_INTERVAL_SECONDS}

def create_session_id(activity_id="",minutes=3):
    raw=f"{activity_id}|{minutes}|{time.time_ns()}|{_RNG.random()}"
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:24]

# Alias para mantener compatibilidad con otros módulos.
catalog=get_catalog
activities=get_activities
session=get_session
plant=get_plant
program_day=get_program_day
health=get_health
config=get_config
